import {
    BooleanColumn,
    DocumentIdColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    Table,
    TableNameColumn,
    UserRolesColumn,
} from '../../db'

export const sys_filter_option_dynamic = Table({
    name: 'sys_filter_option_dynamic',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ mandatory: false, label: 'Active', read_only: false, active: true }),
        available_for_default: BooleanColumn({
            mandatory: false,
            label: 'Available for default',
            read_only: false,
            active: true,
        }),
        available_for_filter: BooleanColumn({
            mandatory: false,
            label: 'Available for filter',
            read_only: false,
            active: true,
        }),
        available_for_ref_qual: BooleanColumn({
            mandatory: false,
            label: 'Available for ref qual',
            read_only: false,
            active: true,
        }),
        field_type: ReferenceColumn({
            mandatory: false,
            label: 'Field type',
            read_only: false,
            active: true,
            referenceTable: 'sys_glide_object',
        }),
        label: StringColumn({
            mandatory: false,
            label: 'Label',
            read_only: false,
            active: true,
            maxLength: 40,
        }),
        order: IntegerColumn({ mandatory: false, label: 'Order', read_only: false, active: true }),
        roles: UserRolesColumn({ mandatory: false, label: 'Roles', read_only: false, active: true }),
        script: StringColumn({ mandatory: false, label: 'Script', read_only: false, active: true, maxLength: 255 }),
        script_reference_id: DocumentIdColumn({
            mandatory: false,
            label: 'Reference script',
            read_only: false,
            active: true,
            dependent: 'script_reference_table',
        }),
        script_reference_table: TableNameColumn({
            mandatory: false,
            label: 'Reference table',
            read_only: false,
            active: true,
        }),
        secondary_script: StringColumn({
            mandatory: false,
            label: 'Secondary Script',
            read_only: false,
            active: true,
            maxLength: 255,
        }),
        table: TableNameColumn({ mandatory: false, label: 'Referenced table', read_only: false, active: true }),
        table_containing_filter: TableNameColumn({
            mandatory: false,
            label: 'Table containing filter',
            read_only: false,
            active: true,
        }),
    },
})
